package com.fileharbor.backend.controller;

import java.io.IOException;
import java.io.InputStream;
import java.net.URI;
import java.util.List;

import com.fileharbor.backend.dto.FileMetadata;
import com.fileharbor.backend.service.FileService;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.web.util.UriComponentsBuilder;

/** HTTP endpoints of the FileHarbor file API. All storage logic lives in {@link FileService}. */
@RestController
@RequestMapping(FileController.BASE_PATH)
public class FileController {

    static final String BASE_PATH = "/api/files";

    private final FileService fileService;

    public FileController(FileService fileService) {
        this.fileService = fileService;
    }

    @PostMapping(consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
    public ResponseEntity<FileMetadata> upload(@RequestParam("file") MultipartFile file) throws IOException {
        if (file.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "File must not be empty.");
        }
        FileMetadata metadata;
        try (InputStream content = file.getInputStream()) {
            metadata = fileService.upload(file.getOriginalFilename(), file.getContentType(), content, file.getSize());
        }
        URI location = UriComponentsBuilder.fromPath(BASE_PATH + "/{id}").buildAndExpand(metadata.id()).toUri();
        return ResponseEntity.created(location).body(metadata);
    }

    @GetMapping
    public List<FileMetadata> list() {
        return fileService.list();
    }
}

package com.fileharbor.backend.controller;

import java.io.IOException;
import java.io.InputStream;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.util.List;

import com.fileharbor.backend.dto.FileMetadata;
import com.fileharbor.backend.service.FileDownload;
import com.fileharbor.backend.service.FileService;
import org.springframework.core.io.InputStreamResource;
import org.springframework.core.io.Resource;
import org.springframework.http.ContentDisposition;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.InvalidMediaTypeException;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.web.util.UriComponentsBuilder;

/** HTTP endpoints of the FileHarbor file API. All storage logic lives in {@link FileService}. */
@RestController
@RequestMapping(FileController.BASE_PATH)
public class FileController {

    static final String BASE_PATH = "/api/files";

    private final FileService fileService;

    public FileController(FileService fileService) {
        this.fileService = fileService;
    }

    @PostMapping(consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
    public ResponseEntity<FileMetadata> upload(@RequestParam("file") MultipartFile file) throws IOException {
        if (file.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "File must not be empty.");
        }
        FileMetadata metadata;
        try (InputStream content = file.getInputStream()) {
            metadata = fileService.upload(file.getOriginalFilename(), file.getContentType(), content, file.getSize());
        }
        URI location = UriComponentsBuilder.fromPath(BASE_PATH + "/{id}").buildAndExpand(metadata.id()).toUri();
        return ResponseEntity.created(location).body(metadata);
    }

    @GetMapping
    public List<FileMetadata> list() {
        return fileService.list();
    }

    /**
     * Streams the file as an attachment. The body is an {@link InputStreamResource}: Spring copies it
     * to the response without buffering the file and closes the stream when writing finishes or fails.
     *
     * <p>A successful {@code FileService.download} only means the file was verified and the stream was
     * opened; bytes are fetched from Azure lazily while the response is written. A failure at that point
     * happens after the status and headers may already be sent, so a {@code ProblemDetail} can no
     * longer be returned and the client sees a truncated response.
     */
    @GetMapping("/{fileId}")
    public ResponseEntity<Resource> download(@PathVariable String fileId) {
        FileDownload download = fileService.download(fileId);
        try {
            FileMetadata metadata = download.metadata();
            return ResponseEntity.ok()
                    .contentType(parseMediaType(metadata.contentType()))
                    .contentLength(metadata.size())
                    .header(HttpHeaders.CONTENT_DISPOSITION, attachment(metadata.originalFilename()).toString())
                    .header("X-Content-Type-Options", "nosniff")
                    .body(new InputStreamResource(download.content()));
        } catch (RuntimeException e) {
            // Building the response failed before Spring took ownership of the stream.
            try {
                download.close();
            } catch (IOException closeFailure) {
                e.addSuppressed(closeFailure);
            }
            throw e;
        }
    }

    /** All validation and eligibility checks live in {@link FileService#delete}; errors map to ProblemDetail. */
    @DeleteMapping("/{fileId}")
    public ResponseEntity<Void> delete(@PathVariable String fileId) {
        fileService.delete(fileId);
        return ResponseEntity.noContent().build();
    }

    /**
     * Built with Spring's {@link ContentDisposition}, never by string concatenation. Plain printable
     * ASCII names use {@code filename="..."} (quotes and backslashes escaped by Spring); anything else is
     * sent as RFC 5987/6266 {@code filename*=UTF-8''...}, which percent-encodes non-ASCII and control characters.
     */
    private static ContentDisposition attachment(String filename) {
        boolean printableAscii = filename.chars().allMatch(c -> c >= 0x20 && c <= 0x7E);
        ContentDisposition.Builder builder = ContentDisposition.attachment();
        return (printableAscii ? builder.filename(filename) : builder.filename(filename, StandardCharsets.UTF_8)).build();
    }

    private static MediaType parseMediaType(String contentType) {
        try {
            return MediaType.parseMediaType(contentType);
        } catch (InvalidMediaTypeException e) {
            return MediaType.APPLICATION_OCTET_STREAM;
        }
    }
}

package com.fileharbor.backend.exception;

import com.fileharbor.backend.controller.FileController;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.HttpStatusCode;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.context.request.WebRequest;
import org.springframework.web.multipart.MaxUploadSizeExceededException;
import org.springframework.web.multipart.support.MissingServletRequestPartException;
import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;

/**
 * Turns every error of the {@code /api/files} API into an {@code application/problem+json}
 * {@link ProblemDetail} with a stable title and a fixed, safe detail message.
 *
 * <p>Exception messages are never copied into responses: they may contain Azure or internal details.
 * The causes of server-side failures are logged instead.
 */
@RestControllerAdvice(assignableTypes = FileController.class)
public class FileExceptionHandler extends ResponseEntityExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(FileExceptionHandler.class);

    // ---- framework exceptions (customized messages) ----

    @Override
    protected ResponseEntity<Object> handleMissingServletRequestPart(MissingServletRequestPartException ex,
            HttpHeaders headers, HttpStatusCode status, WebRequest request) {
        return problem(ex, HttpStatus.BAD_REQUEST, "A file must be uploaded in the multipart field 'file'.", request);
    }

    @Override
    protected ResponseEntity<Object> handleMaxUploadSizeExceededException(MaxUploadSizeExceededException ex,
            HttpHeaders headers, HttpStatusCode status, WebRequest request) {
        return problem(ex, HttpStatus.PAYLOAD_TOO_LARGE, UploadSizeExceptionHandler.DETAIL, request);
    }

    // ---- application exceptions ----

    @ExceptionHandler(InvalidFilenameException.class)
    public ResponseEntity<Object> handleInvalidFilename(InvalidFilenameException ex, WebRequest request) {
        return problem(ex, HttpStatus.BAD_REQUEST, "The uploaded file must have a valid filename.", request);
    }

    @ExceptionHandler(InvalidFileIdException.class)
    public ResponseEntity<Object> handleInvalidFileId(InvalidFileIdException ex, WebRequest request) {
        return problem(ex, HttpStatus.BAD_REQUEST, "The file ID must be a valid UUID.", request);
    }

    @ExceptionHandler(StoredFileNotFoundException.class)
    public ResponseEntity<Object> handleFileNotFound(StoredFileNotFoundException ex, WebRequest request) {
        return problem(ex, HttpStatus.NOT_FOUND, "File not found.", request);
    }

    @ExceptionHandler(FileIdCollisionException.class)
    public ResponseEntity<Object> handleIdCollision(FileIdCollisionException ex, WebRequest request) {
        log.warn("File ID collision while uploading a file");
        return problem(ex, HttpStatus.CONFLICT, "The file could not be stored because of an ID conflict. Please try again.", request);
    }

    @ExceptionHandler(FileStorageException.class)
    public ResponseEntity<Object> handleStorageFailure(FileStorageException ex, WebRequest request) {
        log.error("File storage failure", ex);
        return problem(ex, HttpStatus.SERVICE_UNAVAILABLE, "File storage is temporarily unavailable. Please try again later.", request);
    }

    // ---- everything else ----

    @ExceptionHandler(Exception.class)
    public ResponseEntity<Object> handleUnexpected(Exception ex, WebRequest request) {
        log.error("Unexpected error while handling a file request", ex);
        return problem(ex, HttpStatus.INTERNAL_SERVER_ERROR, "An unexpected error occurred.", request);
    }

    private ResponseEntity<Object> problem(Exception ex, HttpStatus status, String detail, WebRequest request) {
        ProblemDetail body = ProblemDetail.forStatusAndDetail(status, detail);
        body.setTitle(status.getReasonPhrase());
        return handleExceptionInternal(ex, body, new HttpHeaders(), status, request);
    }
}

package com.fileharbor.backend.exception;

/** The uploaded file has no usable filename (missing, or blank after sanitizing). */
public class InvalidFilenameException extends RuntimeException {

    public InvalidFilenameException() {
        super("Filename must not be blank.");
    }
}

package com.fileharbor.backend.exception;

import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.multipart.MaxUploadSizeExceededException;

/**
 * Maps oversized multipart requests to a 413 {@link ProblemDetail}.
 *
 * <p>This advice is deliberately <em>not</em> restricted to {@code FileController}: the container
 * rejects an oversized request while parsing it, before any controller has been chosen, and a
 * controller-scoped advice does not apply at that point. Only this single exception type is handled
 * here, so no other (for example legacy {@code /api/blobs}) error behavior changes.
 */
@RestControllerAdvice
public class UploadSizeExceptionHandler {

    static final String DETAIL = "The uploaded file exceeds the maximum allowed size.";

    @ExceptionHandler(MaxUploadSizeExceededException.class)
    public ResponseEntity<ProblemDetail> handleMaxUploadSize(MaxUploadSizeExceededException ex) {
        ProblemDetail body = ProblemDetail.forStatusAndDetail(HttpStatus.PAYLOAD_TOO_LARGE, DETAIL);
        body.setTitle(HttpStatus.PAYLOAD_TOO_LARGE.getReasonPhrase());
        return ResponseEntity.status(HttpStatus.PAYLOAD_TOO_LARGE).body(body);
    }
}

package com.fileharbor.backend.service;

import java.io.InputStream;
import java.nio.ByteBuffer;
import java.nio.charset.CharacterCodingException;
import java.nio.charset.CodingErrorAction;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.time.OffsetDateTime;
import java.util.ArrayList;
import java.util.Base64;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.UUID;
import java.util.regex.Pattern;

import com.azure.core.exception.AzureException;
import com.azure.core.http.rest.Response;
import com.azure.core.util.Context;
import com.azure.storage.blob.BlobClient;
import com.azure.storage.blob.BlobContainerClient;
import com.azure.storage.blob.models.BlobErrorCode;
import com.azure.storage.blob.models.BlobHttpHeaders;
import com.azure.storage.blob.models.BlobItem;
import com.azure.storage.blob.models.BlobItemProperties;
import com.azure.storage.blob.models.BlobListDetails;
import com.azure.storage.blob.models.BlobProperties;
import com.azure.storage.blob.models.BlobRequestConditions;
import com.azure.storage.blob.models.BlobStorageException;
import com.azure.storage.blob.models.BlockBlobItem;
import com.azure.storage.blob.models.ListBlobsOptions;
import com.azure.storage.blob.options.BlobInputStreamOptions;
import com.azure.storage.blob.options.BlobParallelUploadOptions;
import com.fileharbor.backend.dto.FileMetadata;
import com.fileharbor.backend.exception.FileIdCollisionException;
import com.fileharbor.backend.exception.FileStorageException;
import com.fileharbor.backend.exception.InvalidFileIdException;
import com.fileharbor.backend.exception.StoredFileNotFoundException;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;

/**
 * Stores FileHarbor files in Azure Blob Storage.
 *
 * <p>A blob is a FileHarbor file only if its name is a canonical (lowercase) UUID and it carries a
 * decodable {@value #FILENAME_METADATA_KEY} metadata value. Every other blob (for example one
 * created by the legacy {@code /api/blobs} endpoints) is invisible to this service and is never
 * returned, read or deleted by it.
 *
 * <p><b>Timestamp semantics.</b> {@code uploadedAt} always means the moment the blob was first
 * successfully created. Uploads never overwrite, so a blob's creation time never changes. List and
 * download read Azure's creation-time property; upload uses the {@code Last-Modified} value from the
 * upload response, which for a newly created blob is the same moment, so no extra request is needed.
 * Azure reports these at one-second precision. If Azure supplies no timestamp the value is {@code null}.
 * It is never stored as custom metadata.
 */
@Service
@RequiredArgsConstructor
public class FileService {

    static final String FILENAME_METADATA_KEY = "originalFilename";
    static final String DEFAULT_CONTENT_TYPE = "application/octet-stream";
    private static final int MAX_FILENAME_LENGTH = 255;
    private static final int MAX_CONTENT_TYPE_LENGTH = 255;
    private static final String TOKEN = "[!#$%&'*+.^_`|~0-9A-Za-z-]+";
    private static final String QUOTED_STRING = "\"(?:[ !#-\\[\\]-~]|\\\\[ -~])*\"";
    private static final Pattern MEDIA_TYPE = Pattern.compile(
            TOKEN + "/" + TOKEN + "(?: *; *" + TOKEN + "=(?:" + TOKEN + "|" + QUOTED_STRING + "))*");
    private static final Pattern CANONICAL_UUID =
            Pattern.compile("[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}");

    private final BlobContainerClient containerClient;


    /**
     * Stores a new file under a freshly generated UUID. Existing blobs are never overwritten:
     * the upload carries {@code If-None-Match: *}, so Azure rejects it atomically.
     *
     * @throws IllegalArgumentException if the filename is blank after sanitizing
     * @throws FileIdCollisionException if a blob with the generated ID already exists
     * @throws FileStorageException     on any other storage failure
     */
    public FileMetadata upload(String originalFilename, String contentType, InputStream content, long size) {
        Objects.requireNonNull(content, "content");
        String filename = sanitizeFilename(originalFilename);
        String type = normalizeContentType(contentType);
        UUID id = UUID.randomUUID();

        BlobParallelUploadOptions options = new BlobParallelUploadOptions(content, size)
                .setHeaders(new BlobHttpHeaders().setContentType(type))
                .setMetadata(Map.of(FILENAME_METADATA_KEY, encodeFilename(filename)))
                .setRequestConditions(new BlobRequestConditions().setIfNoneMatch("*"));

        try {
            Response<BlockBlobItem> response = containerClient.getBlobClient(id.toString())
                    .uploadWithResponse(options, null, Context.NONE);
            // Upload response Last-Modified == creation time of a brand-new, never-overwritten blob.
            OffsetDateTime created = response.getValue() == null ? null : response.getValue().getLastModified();
            return new FileMetadata(id, filename, type, size, toInstant(created));
        } catch (BlobStorageException e) {
            if (isAlreadyExists(e)) {
                throw new FileIdCollisionException();
            }
            throw new FileStorageException(e);
        } catch (AzureException e) {
            throw new FileStorageException(e);
        }
    }

    /** Lists valid FileHarbor files, newest first. Legacy and malformed blobs are skipped. */
    public List<FileMetadata> list() {
        ListBlobsOptions options = new ListBlobsOptions()
                .setDetails(new BlobListDetails().setRetrieveMetadata(true));
        List<FileMetadata> files = new ArrayList<>();
        try {
            for (BlobItem item : containerClient.listBlobs(options, null)) {
                toFileMetadata(item).ifPresent(files::add);
            }
        } catch (AzureException e) {
            throw new FileStorageException(e);
        }
        files.sort(Comparator.comparing(FileMetadata::uploadedAt, Comparator.nullsLast(Comparator.reverseOrder()))
                .thenComparing(FileMetadata::id));
        return files;
    }

    /**
     * Opens a streaming download. The stream is pinned to the verified blob's ETag, so it fails
     * rather than returning a blob that changed after verification. The caller must close the result.
     *
     * @throws InvalidFileIdException      if {@code fileId} is not a canonical UUID
     * @throws StoredFileNotFoundException if the file is missing or not a valid FileHarbor file
     * @throws FileStorageException        on any other storage failure
     */
    public FileDownload download(String fileId) {
        VerifiedFile file = verify(parseFileId(fileId));
        try {
            InputStream stream = file.blob().openInputStream(new BlobInputStreamOptions()
                    .setRequestConditions(new BlobRequestConditions().setIfMatch(file.etag())));
            return new FileDownload(file.metadata(), stream);
        } catch (AzureException e) {
            throw translate(e);
        }
    }

    /**
     * Deletes a valid FileHarbor file, only if it is still the exact blob that was verified
     * ({@code If-Match} on its ETag).
     *
     * @throws InvalidFileIdException      if {@code fileId} is not a canonical UUID
     * @throws StoredFileNotFoundException if the file is missing, invalid, or changed since verification
     * @throws FileStorageException        on any other storage failure
     */
    public void delete(String fileId) {
        VerifiedFile file = verify(parseFileId(fileId));
        try {
            file.blob().deleteWithResponse(null, new BlobRequestConditions().setIfMatch(file.etag()), null, Context.NONE);
        } catch (AzureException e) {
            throw translate(e);
        }
    }

    // ---- verification ----

    private record VerifiedFile(BlobClient blob, String etag, FileMetadata metadata) {
    }

    private VerifiedFile verify(UUID id) {
        BlobClient blob = containerClient.getBlobClient(id.toString());
        BlobProperties properties;
        try {
            properties = blob.getProperties();
        } catch (AzureException e) {
            throw translate(e);
        }
        Optional<String> filename = decodeFilename(properties.getMetadata());
        if (filename.isEmpty()) {
            throw new StoredFileNotFoundException();
        }
        String etag = properties.getETag();
        if (etag == null || etag.isBlank()) {
            // Without an ETag the If-Match protection cannot be applied, so refuse to continue.
            throw new FileStorageException("Storage did not return an ETag for the blob.");
        }
        FileMetadata metadata = new FileMetadata(id, filename.get(), normalizeContentType(properties.getContentType()),
                properties.getBlobSize(), toInstant(properties.getCreationTime()));
        return new VerifiedFile(blob, etag, metadata);
    }

    private static Optional<FileMetadata> toFileMetadata(BlobItem item) {
        String name = item.getName();
        BlobItemProperties properties = item.getProperties();
        if (item.isDeleted() || name == null || !CANONICAL_UUID.matcher(name).matches()
                || properties == null || properties.getContentLength() == null) {
            return Optional.empty();
        }
        return decodeFilename(item.getMetadata()).map(filename -> new FileMetadata(
                UUID.fromString(name),
                filename,
                normalizeContentType(properties.getContentType()),
                properties.getContentLength(),
                toInstant(properties.getCreationTime())));
    }

    // ---- helpers ----

    /** Accepts upper or lower case hex, but only the canonical 8-4-4-4-12 form; normalizes to lowercase. */
    static UUID parseFileId(String fileId) {
        if (fileId == null) {
            throw new InvalidFileIdException();
        }
        String normalized = fileId.toLowerCase(Locale.ROOT);
        if (!CANONICAL_UUID.matcher(normalized).matches()) {
            throw new InvalidFileIdException();
        }
        return UUID.fromString(normalized);
    }

    static String encodeFilename(String filename) {
        return Base64.getUrlEncoder().withoutPadding().encodeToString(filename.getBytes(StandardCharsets.UTF_8));
    }

    /** Decodes the filename metadata (key matched case-insensitively); empty if absent, blank or malformed. */
    static Optional<String> decodeFilename(Map<String, String> metadata) {
        if (metadata == null) {
            return Optional.empty();
        }
        return metadata.entrySet().stream()
                .filter(entry -> FILENAME_METADATA_KEY.equalsIgnoreCase(entry.getKey()))
                .map(Map.Entry::getValue)
                .filter(Objects::nonNull)
                .findFirst()
                .flatMap(FileService::decodeBase64Utf8);
    }

    private static Optional<String> decodeBase64Utf8(String encoded) {
        try {
            byte[] bytes = Base64.getUrlDecoder().decode(encoded);
            String decoded = StandardCharsets.UTF_8.newDecoder()
                    .onMalformedInput(CodingErrorAction.REPORT)
                    .onUnmappableCharacter(CodingErrorAction.REPORT)
                    .decode(ByteBuffer.wrap(bytes))
                    .toString();
            return decoded.isBlank() ? Optional.empty() : Optional.of(decoded);
        } catch (IllegalArgumentException | CharacterCodingException e) {
            return Optional.empty();
        }
    }

    /** Display label only: drops directory parts and control characters and caps the length. */
    static String sanitizeFilename(String filename) {
        if (filename == null) {
            throw new IllegalArgumentException("Filename must not be blank.");
        }
        String base = filename.substring(Math.max(filename.lastIndexOf('/'), filename.lastIndexOf('\\')) + 1)
                .replaceAll("\\p{Cc}", "")
                .strip();
        int[] codePoints = base.codePoints().limit(MAX_FILENAME_LENGTH).toArray();
        String result = new String(codePoints, 0, codePoints.length).strip();
        if (result.isEmpty()) {
            throw new IllegalArgumentException("Filename must not be blank.");
        }
        return result;
    }

    /**
     * The client-supplied type is only an untrusted label. It is kept only if it is a syntactically
     * valid, concrete media type ({@code type/subtype} with optional {@code ; name=value} parameters,
     * RFC 9110 tokens); anything else (null, blank, control characters, malformed, wildcard, too
     * long) falls back to {@code application/octet-stream}. No claim is made that the content
     * actually matches the type.
     */
    static String normalizeContentType(String contentType) {
        if (contentType == null || contentType.chars().anyMatch(Character::isISOControl)) {
            return DEFAULT_CONTENT_TYPE; // checked on the raw value: strip() would hide a trailing CR/LF
        }
        String stripped = contentType.strip();
        if (stripped.isEmpty() || stripped.length() > MAX_CONTENT_TYPE_LENGTH
                || !MEDIA_TYPE.matcher(stripped).matches()) {
            return DEFAULT_CONTENT_TYPE;
        }
        String essence = stripped.split(";", 2)[0].strip();
        if (essence.startsWith("*/") || essence.endsWith("/*")) {
            return DEFAULT_CONTENT_TYPE;
        }
        return stripped;
    }

    private static Instant toInstant(OffsetDateTime time) {
        return time == null ? null : time.toInstant();
    }

    /**
     * True only when Azure reports that the blob already exists. The upload sends nothing but
     * {@code If-None-Match: *}, so the two outcomes that mean "the blob exists" are:
     * <ul>
     *   <li>error code {@code BlobAlreadyExists} (Azure answers 409 for this), or</li>
     *   <li>HTTP 412 with error code {@code ConditionNotMet}, i.e. the precondition failed.</li>
     * </ul>
     * Any other 409 (for example {@code ContainerBeingDeleted}) or any 412 without
     * {@code ConditionNotMet} is an unrelated storage failure and is not reported as a collision.
     */
    private static boolean isAlreadyExists(BlobStorageException e) {
        BlobErrorCode code = e.getErrorCode();
        if (BlobErrorCode.BLOB_ALREADY_EXISTS.equals(code)) {
            return true;
        }
        return e.getStatusCode() == 412 && BlobErrorCode.CONDITION_NOT_MET.equals(code);
    }

    /** 404 (missing) and 412 (changed since verification) both mean "nothing safe to act on". */
    private static RuntimeException translate(AzureException e) {
        if (e instanceof BlobStorageException storageException
                && (storageException.getStatusCode() == 404 || storageException.getStatusCode() == 412)) {
            return new StoredFileNotFoundException();
        }
        return new FileStorageException(e);
    }
}

package com.fileharbor.backend.service;

import java.io.InputStream;
import java.nio.ByteBuffer;
import java.nio.charset.CharacterCodingException;
import java.nio.charset.CodingErrorAction;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.time.OffsetDateTime;
import java.util.ArrayList;
import java.util.Base64;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.UUID;
import java.util.regex.Pattern;

import com.azure.core.exception.AzureException;
import com.azure.core.http.rest.Response;
import com.azure.core.util.Context;
import com.azure.storage.blob.BlobClient;
import com.azure.storage.blob.BlobContainerClient;
import com.azure.storage.blob.models.BlobErrorCode;
import com.azure.storage.blob.models.BlobHttpHeaders;
import com.azure.storage.blob.models.BlobItem;
import com.azure.storage.blob.models.BlobItemProperties;
import com.azure.storage.blob.models.BlobListDetails;
import com.azure.storage.blob.models.BlobProperties;
import com.azure.storage.blob.models.BlobRequestConditions;
import com.azure.storage.blob.models.BlobStorageException;
import com.azure.storage.blob.models.BlockBlobItem;
import com.azure.storage.blob.models.ListBlobsOptions;
import com.azure.storage.blob.options.BlobInputStreamOptions;
import com.azure.storage.blob.options.BlobParallelUploadOptions;
import com.fileharbor.backend.dto.FileMetadata;
import com.fileharbor.backend.exception.FileIdCollisionException;
import com.fileharbor.backend.exception.FileStorageException;
import com.fileharbor.backend.exception.InvalidFileIdException;
import com.fileharbor.backend.exception.InvalidFilenameException;
import com.fileharbor.backend.exception.StoredFileNotFoundException;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;

/**
 * Stores FileHarbor files in Azure Blob Storage.
 *
 * <p>A blob is a FileHarbor file only if its name is a canonical (lowercase) UUID and it carries a
 * decodable {@value #FILENAME_METADATA_KEY} metadata value. Every other blob (for example one
 * created by the legacy {@code /api/blobs} endpoints) is invisible to this service and is never
 * returned, read or deleted by it.
 *
 * <p><b>Timestamp semantics.</b> {@code uploadedAt} always means the moment the blob was first
 * successfully created. Uploads never overwrite, so a blob's creation time never changes. List and
 * download read Azure's creation-time property; upload uses the {@code Last-Modified} value from the
 * upload response, which for a newly created blob is the same moment, so no extra request is needed.
 * Azure reports these at one-second precision. If Azure supplies no timestamp the value is {@code null}.
 * It is never stored as custom metadata.
 */
@Service
@RequiredArgsConstructor
public class FileService {

    static final String FILENAME_METADATA_KEY = "originalFilename";
    static final String DEFAULT_CONTENT_TYPE = "application/octet-stream";
    private static final int MAX_FILENAME_LENGTH = 255;
    private static final int MAX_CONTENT_TYPE_LENGTH = 255;
    private static final String TOKEN = "[!#$%&'*+.^_`|~0-9A-Za-z-]+";
    private static final String QUOTED_STRING = "\"(?:[ !#-\\[\\]-~]|\\\\[ -~])*\"";
    private static final Pattern MEDIA_TYPE = Pattern.compile(
            TOKEN + "/" + TOKEN + "(?: *; *" + TOKEN + "=(?:" + TOKEN + "|" + QUOTED_STRING + "))*");
    private static final Pattern CANONICAL_UUID =
            Pattern.compile("[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}");

    private final BlobContainerClient containerClient;


    /**
     * Stores a new file under a freshly generated UUID. Existing blobs are never overwritten:
     * the upload carries {@code If-None-Match: *}, so Azure rejects it atomically.
     *
     * @throws InvalidFilenameException if the filename is missing or blank after sanitizing
     * @throws FileIdCollisionException if a blob with the generated ID already exists
     * @throws FileStorageException     on any other storage failure
     */
    public FileMetadata upload(String originalFilename, String contentType, InputStream content, long size) {
        Objects.requireNonNull(content, "content");
        String filename = sanitizeFilename(originalFilename);
        String type = normalizeContentType(contentType);
        UUID id = UUID.randomUUID();

        BlobParallelUploadOptions options = new BlobParallelUploadOptions(content, size)
                .setHeaders(new BlobHttpHeaders().setContentType(type))
                .setMetadata(Map.of(FILENAME_METADATA_KEY, encodeFilename(filename)))
                .setRequestConditions(new BlobRequestConditions().setIfNoneMatch("*"));

        try {
            Response<BlockBlobItem> response = containerClient.getBlobClient(id.toString())
                    .uploadWithResponse(options, null, Context.NONE);
            // Upload response Last-Modified == creation time of a brand-new, never-overwritten blob.
            OffsetDateTime created = response.getValue() == null ? null : response.getValue().getLastModified();
            return new FileMetadata(id, filename, type, size, toInstant(created));
        } catch (BlobStorageException e) {
            if (isAlreadyExists(e)) {
                throw new FileIdCollisionException();
            }
            throw new FileStorageException(e);
        } catch (AzureException e) {
            throw new FileStorageException(e);
        }
    }

    /** Lists valid FileHarbor files, newest first. Legacy and malformed blobs are skipped. */
    public List<FileMetadata> list() {
        ListBlobsOptions options = new ListBlobsOptions()
                .setDetails(new BlobListDetails().setRetrieveMetadata(true));
        List<FileMetadata> files = new ArrayList<>();
        try {
            for (BlobItem item : containerClient.listBlobs(options, null)) {
                toFileMetadata(item).ifPresent(files::add);
            }
        } catch (AzureException e) {
            throw new FileStorageException(e);
        }
        files.sort(Comparator.comparing(FileMetadata::uploadedAt, Comparator.nullsLast(Comparator.reverseOrder()))
                .thenComparing(FileMetadata::id));
        return files;
    }

    /**
     * Opens a streaming download. The stream is pinned to the verified blob's ETag, so it fails
     * rather than returning a blob that changed after verification. The caller must close the result.
     *
     * @throws InvalidFileIdException      if {@code fileId} is not a canonical UUID
     * @throws StoredFileNotFoundException if the file is missing or not a valid FileHarbor file
     * @throws FileStorageException        on any other storage failure
     */
    public FileDownload download(String fileId) {
        VerifiedFile file = verify(parseFileId(fileId));
        try {
            InputStream stream = file.blob().openInputStream(new BlobInputStreamOptions()
                    .setRequestConditions(new BlobRequestConditions().setIfMatch(file.etag())));
            return new FileDownload(file.metadata(), stream);
        } catch (AzureException e) {
            throw translate(e);
        }
    }

    /**
     * Deletes a valid FileHarbor file, only if it is still the exact blob that was verified
     * ({@code If-Match} on its ETag).
     *
     * @throws InvalidFileIdException      if {@code fileId} is not a canonical UUID
     * @throws StoredFileNotFoundException if the file is missing, invalid, or changed since verification
     * @throws FileStorageException        on any other storage failure
     */
    public void delete(String fileId) {
        VerifiedFile file = verify(parseFileId(fileId));
        try {
            file.blob().deleteWithResponse(null, new BlobRequestConditions().setIfMatch(file.etag()), null, Context.NONE);
        } catch (AzureException e) {
            throw translate(e);
        }
    }

    // ---- verification ----

    private record VerifiedFile(BlobClient blob, String etag, FileMetadata metadata) {
    }

    private VerifiedFile verify(UUID id) {
        BlobClient blob = containerClient.getBlobClient(id.toString());
        BlobProperties properties;
        try {
            properties = blob.getProperties();
        } catch (AzureException e) {
            throw translate(e);
        }
        Optional<String> filename = decodeFilename(properties.getMetadata());
        if (filename.isEmpty()) {
            throw new StoredFileNotFoundException();
        }
        String etag = properties.getETag();
        if (etag == null || etag.isBlank()) {
            // Without an ETag the If-Match protection cannot be applied, so refuse to continue.
            throw new FileStorageException("Storage did not return an ETag for the blob.");
        }
        FileMetadata metadata = new FileMetadata(id, filename.get(), normalizeContentType(properties.getContentType()),
                properties.getBlobSize(), toInstant(properties.getCreationTime()));
        return new VerifiedFile(blob, etag, metadata);
    }

    private static Optional<FileMetadata> toFileMetadata(BlobItem item) {
        String name = item.getName();
        BlobItemProperties properties = item.getProperties();
        if (item.isDeleted() || name == null || !CANONICAL_UUID.matcher(name).matches()
                || properties == null || properties.getContentLength() == null) {
            return Optional.empty();
        }
        return decodeFilename(item.getMetadata()).map(filename -> new FileMetadata(
                UUID.fromString(name),
                filename,
                normalizeContentType(properties.getContentType()),
                properties.getContentLength(),
                toInstant(properties.getCreationTime())));
    }

    // ---- helpers ----

    /** Accepts upper or lower case hex, but only the canonical 8-4-4-4-12 form; normalizes to lowercase. */
    static UUID parseFileId(String fileId) {
        if (fileId == null) {
            throw new InvalidFileIdException();
        }
        String normalized = fileId.toLowerCase(Locale.ROOT);
        if (!CANONICAL_UUID.matcher(normalized).matches()) {
            throw new InvalidFileIdException();
        }
        return UUID.fromString(normalized);
    }

    static String encodeFilename(String filename) {
        return Base64.getUrlEncoder().withoutPadding().encodeToString(filename.getBytes(StandardCharsets.UTF_8));
    }

    /** Decodes the filename metadata (key matched case-insensitively); empty if absent, blank or malformed. */
    static Optional<String> decodeFilename(Map<String, String> metadata) {
        if (metadata == null) {
            return Optional.empty();
        }
        return metadata.entrySet().stream()
                .filter(entry -> FILENAME_METADATA_KEY.equalsIgnoreCase(entry.getKey()))
                .map(Map.Entry::getValue)
                .filter(Objects::nonNull)
                .findFirst()
                .flatMap(FileService::decodeBase64Utf8);
    }

    private static Optional<String> decodeBase64Utf8(String encoded) {
        try {
            byte[] bytes = Base64.getUrlDecoder().decode(encoded);
            String decoded = StandardCharsets.UTF_8.newDecoder()
                    .onMalformedInput(CodingErrorAction.REPORT)
                    .onUnmappableCharacter(CodingErrorAction.REPORT)
                    .decode(ByteBuffer.wrap(bytes))
                    .toString();
            return decoded.isBlank() ? Optional.empty() : Optional.of(decoded);
        } catch (IllegalArgumentException | CharacterCodingException e) {
            return Optional.empty();
        }
    }

    /** Display label only: drops directory parts and control characters and caps the length. */
    static String sanitizeFilename(String filename) {
        if (filename == null) {
            throw new InvalidFilenameException();
        }
        String base = filename.substring(Math.max(filename.lastIndexOf('/'), filename.lastIndexOf('\\')) + 1)
                .replaceAll("\\p{Cc}", "")
                .strip();
        int[] codePoints = base.codePoints().limit(MAX_FILENAME_LENGTH).toArray();
        String result = new String(codePoints, 0, codePoints.length).strip();
        if (result.isEmpty()) {
            throw new InvalidFilenameException();
        }
        return result;
    }

    /**
     * The client-supplied type is only an untrusted label. It is kept only if it is a syntactically
     * valid, concrete media type ({@code type/subtype} with optional {@code ; name=value} parameters,
     * RFC 9110 tokens); anything else (null, blank, control characters, malformed, wildcard, too
     * long) falls back to {@code application/octet-stream}. No claim is made that the content
     * actually matches the type.
     */
    static String normalizeContentType(String contentType) {
        if (contentType == null || contentType.chars().anyMatch(Character::isISOControl)) {
            return DEFAULT_CONTENT_TYPE; // checked on the raw value: strip() would hide a trailing CR/LF
        }
        String stripped = contentType.strip();
        if (stripped.isEmpty() || stripped.length() > MAX_CONTENT_TYPE_LENGTH
                || !MEDIA_TYPE.matcher(stripped).matches()) {
            return DEFAULT_CONTENT_TYPE;
        }
        String essence = stripped.split(";", 2)[0].strip();
        if (essence.startsWith("*/") || essence.endsWith("/*")) {
            return DEFAULT_CONTENT_TYPE;
        }
        return stripped;
    }

    private static Instant toInstant(OffsetDateTime time) {
        return time == null ? null : time.toInstant();
    }

    /**
     * True only when Azure reports that the blob already exists. The upload sends nothing but
     * {@code If-None-Match: *}, so the two outcomes that mean "the blob exists" are:
     * <ul>
     *   <li>error code {@code BlobAlreadyExists} (Azure answers 409 for this), or</li>
     *   <li>HTTP 412 with error code {@code ConditionNotMet}, i.e. the precondition failed.</li>
     * </ul>
     * Any other 409 (for example {@code ContainerBeingDeleted}) or any 412 without
     * {@code ConditionNotMet} is an unrelated storage failure and is not reported as a collision.
     */
    private static boolean isAlreadyExists(BlobStorageException e) {
        BlobErrorCode code = e.getErrorCode();
        if (BlobErrorCode.BLOB_ALREADY_EXISTS.equals(code)) {
            return true;
        }
        return e.getStatusCode() == 412 && BlobErrorCode.CONDITION_NOT_MET.equals(code);
    }

    /** 404 (missing) and 412 (changed since verification) both mean "nothing safe to act on". */
    private static RuntimeException translate(AzureException e) {
        if (e instanceof BlobStorageException storageException
                && (storageException.getStatusCode() == 404 || storageException.getStatusCode() == 412)) {
            return new StoredFileNotFoundException();
        }
        return new FileStorageException(e);
    }
}

package com.fileharbor.backend.controller;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.verifyNoInteractions;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.List;

import com.fileharbor.backend.service.FileService;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.bean.override.mockito.MockitoBean;

/**
 * Runs the real embedded server with the real multipart configuration from {@code application.yaml}
 * (20 MB). MockMvc cannot be used here: it does not enforce the container's multipart limits.
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT, properties = {
        // Fake, non-secret values: building the Azure client does not contact Azure.
        "azure.storage.connection-string=DefaultEndpointsProtocol=https;AccountName=testaccount;AccountKey=dGVzdA==;EndpointSuffix=core.windows.net",
        "azure.storage.blob-container-name=test-container"
})
class FileApiSizeLimitIntegrationTest {

    private static final String BOUNDARY = "----fileharbor-test-boundary";

    @Value("${local.server.port}")
    private int port;

    @MockitoBean
    private FileService fileService;

    @Test
    void uploadLargerThanConfiguredLimitReturns413ProblemDetail() throws Exception {
        byte[] content = new byte[21 * 1024 * 1024];
        Arrays.fill(content, (byte) 'a');

        HttpResponse<String> response = post(content);

        assertEquals(413, response.statusCode());
        assertTrue(response.headers().firstValue("Content-Type").orElse("").startsWith("application/problem+json"),
                "content type was " + response.headers().firstValue("Content-Type"));
        assertTrue(response.body().contains("\"status\":413"), response.body());
        assertTrue(response.body().contains("The uploaded file exceeds the maximum allowed size."), response.body());
        assertFalse(response.body().contains("Exception"), "must not expose exception details: " + response.body());
        verifyNoInteractions(fileService);
    }

    private HttpResponse<String> post(byte[] content) throws Exception {
        byte[] head = ("--" + BOUNDARY + "\r\n"
                + "Content-Disposition: form-data; name=\"file\"; filename=\"big.bin\"\r\n"
                + "Content-Type: application/octet-stream\r\n\r\n").getBytes(StandardCharsets.UTF_8);
        byte[] tail = ("\r\n--" + BOUNDARY + "--\r\n").getBytes(StandardCharsets.UTF_8);

        HttpRequest request = HttpRequest.newBuilder(URI.create("http://localhost:" + port + "/api/files"))
                .header("Content-Type", "multipart/form-data; boundary=" + BOUNDARY)
                .POST(HttpRequest.BodyPublishers.ofByteArrays(List.of(head, content, tail)))
                .build();
        return HttpClient.newHttpClient().send(request, HttpResponse.BodyHandlers.ofString());
    }
}

package com.fileharbor.backend.controller;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoMoreInteractions;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.util.UUID;

import com.fileharbor.backend.exception.FileStorageException;
import com.fileharbor.backend.exception.InvalidFileIdException;
import com.fileharbor.backend.exception.StoredFileNotFoundException;
import com.fileharbor.backend.service.FileService;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;
import org.springframework.http.MediaType;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;

@WebMvcTest(FileController.class)
class FileDeleteControllerTest {

    private static final UUID ID = UUID.fromString("3f2b8c1e-6d4a-4b7e-9a51-0c2f7d9e1a44");
    private static final String SECRET = "SECRET-azure-account-details";

    @Autowired
    private MockMvc mockMvc;

    @MockitoBean
    private FileService fileService;

    @Test
    void delete_returns204WithEmptyBodyAndCallsServiceExactlyOnce() throws Exception {
        MvcResult result = mockMvc.perform(delete("/api/files/{id}", ID))
                .andExpect(status().isNoContent())
                .andExpect(content().string(""))
                .andReturn();

        assertEquals(0, result.getResponse().getContentAsByteArray().length);
        assertEquals(null, result.getResponse().getContentType(), "a 204 must not declare a body type");
        verify(fileService, times(1)).delete(ID.toString());
        verifyNoMoreInteractions(fileService);
    }

    @Test
    void delete_passesTheIdExactlyAsSuppliedToTheService() throws Exception {
        String upperCase = ID.toString().toUpperCase();

        mockMvc.perform(delete("/api/files/{id}", upperCase)).andExpect(status().isNoContent());

        verify(fileService).delete(upperCase);
    }

    @Test
    void delete_isNeither200Nor202() throws Exception {
        int status = mockMvc.perform(delete("/api/files/{id}", ID)).andReturn().getResponse().getStatus();

        assertEquals(204, status);
    }

    @Test
    void delete_invalidId_returns400ProblemDetail() throws Exception {
        doThrow(new InvalidFileIdException()).when(fileService).delete("not-a-uuid");

        mockMvc.perform(delete("/api/files/not-a-uuid"))
                .andExpect(status().isBadRequest())
                .andExpect(content().contentTypeCompatibleWith(MediaType.APPLICATION_PROBLEM_JSON))
                .andExpect(jsonPath("$.status").value(400))
                .andExpect(jsonPath("$.title").value("Bad Request"))
                .andExpect(jsonPath("$.detail").value("The file ID must be a valid UUID."));
    }

    @Test
    void delete_missingFile_returns404ProblemDetail() throws Exception {
        doThrow(new StoredFileNotFoundException()).when(fileService).delete(ID.toString());

        mockMvc.perform(delete("/api/files/{id}", ID))
                .andExpect(status().isNotFound())
                .andExpect(content().contentTypeCompatibleWith(MediaType.APPLICATION_PROBLEM_JSON))
                .andExpect(jsonPath("$.status").value(404))
                .andExpect(jsonPath("$.title").value("Not Found"))
                .andExpect(jsonPath("$.detail").value("File not found."));
    }

    @Test
    void delete_storageFailure_returns503ProblemDetailWithoutAzureDetails() throws Exception {
        doThrow(new FileStorageException(new RuntimeException(SECRET))).when(fileService).delete(ID.toString());

        MvcResult result = mockMvc.perform(delete("/api/files/{id}", ID))
                .andExpect(status().isServiceUnavailable())
                .andExpect(content().contentTypeCompatibleWith(MediaType.APPLICATION_PROBLEM_JSON))
                .andExpect(jsonPath("$.status").value(503))
                .andExpect(jsonPath("$.title").value("Service Unavailable"))
                .andExpect(jsonPath("$.detail").value("File storage is temporarily unavailable. Please try again later."))
                .andReturn();

        assertFalse(result.getResponse().getContentAsString().contains(SECRET));
    }

    @Test
    void delete_failuresNeverProduceASuccessfulResponse() throws Exception {
        RuntimeException[] failures = {
                new InvalidFileIdException(),
                new StoredFileNotFoundException(),
                new FileStorageException(new RuntimeException(SECRET)),
                new FileStorageException(SECRET),
                new IllegalStateException(SECRET)};

        for (RuntimeException failure : failures) {
            doThrow(failure).when(fileService).delete(ID.toString());

            MvcResult result = mockMvc.perform(delete("/api/files/{id}", ID)).andReturn();

            int status = result.getResponse().getStatus();
            assertNotEquals(204, status, failure.getClass().getSimpleName());
            assertTrue(status >= 400, failure.getClass().getSimpleName() + " -> " + status);
            assertTrue(result.getResponse().getContentType().startsWith("application/problem+json"));
            assertFalse(result.getResponse().getContentAsString().contains(SECRET));
        }
    }
}

package com.fileharbor.backend.controller;

import static org.mockito.Mockito.verifyNoInteractions;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import com.azure.storage.blob.BlobContainerClient;
import com.fileharbor.backend.service.FileService;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;
import org.springframework.context.annotation.Import;
import org.springframework.http.MediaType;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;

/**
 * UUID validation lives in {@link FileService} (single source of truth), not in the controller. This test
 * uses the <em>real</em> service over a mocked Azure container client to prove that an invalid ID is rejected
 * with a 400 {@code ProblemDetail} before any storage operation happens.
 */
@WebMvcTest(FileController.class)
@Import(FileService.class)
class FileDeleteValidationTest {

    @Autowired
    private MockMvc mockMvc;

    @MockitoBean
    private BlobContainerClient containerClient;

    @Test
    void invalidIds_return400ProblemDetailAndNeverTouchStorage() throws Exception {
        for (String invalid : new String[]{
                "not-a-uuid",
                "1-1-1-1-1",
                "3f2b8c1e6d4a4b7e9a510c2f7d9e1a44",
                "3f2b8c1e-6d4a-4b7e-9a51-0c2f7d9e1a4",
                "3f2b8c1e-6d4a-4b7e-9a51-0c2f7d9e1a44x",
                "..%20"}) {
            mockMvc.perform(delete("/api/files/{id}", invalid))
                    .andExpect(status().isBadRequest())
                    .andExpect(content().contentTypeCompatibleWith(MediaType.APPLICATION_PROBLEM_JSON))
                    .andExpect(jsonPath("$.status").value(400))
                    .andExpect(jsonPath("$.detail").value("The file ID must be a valid UUID."));
        }

        verifyNoInteractions(containerClient);
    }
}

package com.fileharbor.backend.controller;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.multipart;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.io.InputStream;

import com.fileharbor.backend.exception.FileIdCollisionException;
import com.fileharbor.backend.exception.FileStorageException;
import com.fileharbor.backend.exception.InvalidFileIdException;
import com.fileharbor.backend.exception.InvalidFilenameException;
import com.fileharbor.backend.exception.StoredFileNotFoundException;
import com.fileharbor.backend.service.FileService;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;
import org.springframework.http.MediaType;
import org.springframework.mock.web.MockMultipartFile;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.ResultActions;
import org.springframework.web.multipart.MaxUploadSizeExceededException;

/**
 * Verifies that every error of the files API is an {@code application/problem+json}
 * {@code ProblemDetail} with a fixed, safe message. Oversized requests that are rejected by the
 * real container are covered by {@link FileApiSizeLimitIntegrationTest}.
 */
@WebMvcTest(FileController.class)
class FileExceptionHandlingTest {

    private static final String SECRET = "SECRET-azure-account-details";

    @Autowired
    private MockMvc mockMvc;

    @MockitoBean
    private FileService fileService;

    @Test
    void missingMultipartPart_returns400ProblemDetail() throws Exception {
        ResultActions result = mockMvc.perform(multipart("/api/files"));

        assertProblem(result, 400, "Bad Request", "A file must be uploaded in the multipart field 'file'.");
        verifyNoInteractions(fileService);
    }

    @Test
    void emptyFile_returns400ProblemDetail() throws Exception {
        ResultActions result = mockMvc.perform(multipart("/api/files")
                .file(new MockMultipartFile("file", "empty.txt", "text/plain", new byte[0])));

        assertProblem(result, 400, "Bad Request", "File must not be empty.");
        verifyNoInteractions(fileService);
    }

    @Test
    void invalidFilename_returns400ProblemDetail() throws Exception {
        whenUploadThrows(new InvalidFilenameException());

        assertProblem(uploadSomething(), 400, "Bad Request", "The uploaded file must have a valid filename.");
    }

    @Test
    void invalidFileId_returns400ProblemDetail() throws Exception {
        whenUploadThrows(new InvalidFileIdException());

        assertProblem(uploadSomething(), 400, "Bad Request", "The file ID must be a valid UUID.");
    }

    @Test
    void oversizedMultipartRequest_returns413ProblemDetail() throws Exception {
        whenUploadThrows(new MaxUploadSizeExceededException(20L * 1024 * 1024));

        assertProblem(uploadSomething(), 413, "Payload Too Large", "The uploaded file exceeds the maximum allowed size.");
    }

    @Test
    void idCollision_returns409ProblemDetail() throws Exception {
        whenUploadThrows(new FileIdCollisionException());

        assertProblem(uploadSomething(), 409, "Conflict",
                "The file could not be stored because of an ID conflict. Please try again.");
    }

    @Test
    void fileNotFound_returns404ProblemDetail() throws Exception {
        whenUploadThrows(new StoredFileNotFoundException());

        assertProblem(uploadSomething(), 404, "Not Found", "File not found.");
    }

    @Test
    void storageFailure_returns503ProblemDetailWithoutAzureDetails() throws Exception {
        whenUploadThrows(new FileStorageException(new RuntimeException(SECRET)));

        ResultActions result = uploadSomething();

        assertProblem(result, 503, "Service Unavailable",
                "File storage is temporarily unavailable. Please try again later.");
        assertDoesNotExpose(result, SECRET);
    }

    @Test
    void storageFailureWithCustomMessage_doesNotExposeTheMessage() throws Exception {
        whenUploadThrows(new FileStorageException(SECRET));

        ResultActions result = uploadSomething();

        assertProblem(result, 503, "Service Unavailable",
                "File storage is temporarily unavailable. Please try again later.");
        assertDoesNotExpose(result, SECRET);
    }

    @Test
    void unexpectedException_returns500ProblemDetailWithoutInternalDetails() throws Exception {
        whenUploadThrows(new IllegalStateException(SECRET));

        ResultActions result = uploadSomething();

        assertProblem(result, 500, "Internal Server Error", "An unexpected error occurred.");
        assertDoesNotExpose(result, SECRET);
        assertDoesNotExpose(result, "IllegalStateException");
    }

    @Test
    void unexpectedExceptionWhileListing_returns500ProblemDetail() throws Exception {
        when(fileService.list()).thenThrow(new NullPointerException(SECRET));

        ResultActions result = mockMvc.perform(get("/api/files"));

        assertProblem(result, 500, "Internal Server Error", "An unexpected error occurred.");
        assertDoesNotExpose(result, SECRET);
    }

    @Test
    void storageFailureWhileListing_returns503ProblemDetail() throws Exception {
        when(fileService.list()).thenThrow(new FileStorageException(new RuntimeException(SECRET)));

        ResultActions result = mockMvc.perform(get("/api/files"));

        assertProblem(result, 503, "Service Unavailable",
                "File storage is temporarily unavailable. Please try again later.");
        assertDoesNotExpose(result, SECRET);
    }

    // --------------------------------------------------------------- helpers

    private void whenUploadThrows(RuntimeException exception) {
        when(fileService.upload(any(), any(), any(InputStream.class), anyLong())).thenThrow(exception);
    }

    private ResultActions uploadSomething() throws Exception {
        return mockMvc.perform(multipart("/api/files")
                .file(new MockMultipartFile("file", "a.txt", "text/plain", new byte[]{1, 2, 3})));
    }

    private static void assertProblem(ResultActions result, int status, String title, String detail) throws Exception {
        result.andExpect(status().is(status))
                .andExpect(content().contentTypeCompatibleWith(MediaType.APPLICATION_PROBLEM_JSON))
                .andExpect(jsonPath("$.status").value(status))
                .andExpect(jsonPath("$.title").value(title))
                .andExpect(jsonPath("$.detail").value(detail))
                .andExpect(jsonPath("$.trace").doesNotExist())
                .andExpect(jsonPath("$.exception").doesNotExist())
                .andExpect(jsonPath("$.stackTrace").doesNotExist());
    }

    private static void assertDoesNotExpose(ResultActions result, String internal) throws Exception {
        String body = result.andReturn().getResponse().getContentAsString();
        assertFalse(body.contains(internal), "response must not contain '" + internal + "': " + body);
    }
}

package com.fileharbor.backend.service;

